/** Reason one generic parameter was induced. */
export type GenericParameterInduction = "parameterConstraint" | "storageConstraint" | "form" | "comptime";

export const GenericParameterInduction = {
    /** Encode this value. */
    encode(writer: BinaryWriter, value: GenericParameterInduction): void {
        encodeGenericParameterInduction(writer, value);
    },

    /** Decode one GenericParameterInduction. */
    decode(reader: BinaryReader): GenericParameterInduction {
        return decodeGenericParameterInduction(reader);
    },

    /** Return this value as JSON. */
    toJson(value: GenericParameterInduction): Json {
        return toJsonGenericParameterInduction(value);
    },

    /** Return one GenericParameterInduction from one JSON value. */
    fromJson(value: Json): GenericParameterInduction {
        return fromJsonGenericParameterInduction(value);
    },
};

/** Encode one GenericParameterInduction. */
export function encodeGenericParameterInduction(writer: BinaryWriter, value: GenericParameterInduction): void {
    switch (value) {
        case "parameterConstraint":
            writer.writeUnsigned(0);
            return;
        case "storageConstraint":
            writer.writeUnsigned(1);
            return;
        case "form":
            writer.writeUnsigned(2);
            return;
        case "comptime":
            writer.writeUnsigned(3);
            return;
    }

    throw new SerdeError("unknown enum variant");
}

/** Decode one GenericParameterInduction. */
export function decodeGenericParameterInduction(reader: BinaryReader): GenericParameterInduction {
    const variant = reader.readNumber();

    switch (variant) {
        case 0:
            return "parameterConstraint";
        case 1:
            return "storageConstraint";
        case 2:
            return "form";
        case 3:
            return "comptime";
    }

    throw new SerdeError(`unknown enum variant index: ${variant}`);
}

/** Return one JSON value for one GenericParameterInduction. */
export function toJsonGenericParameterInduction(value: GenericParameterInduction): Json {
    return value;
}

/** Return one GenericParameterInduction from one JSON value. */
export function fromJsonGenericParameterInduction(value: Json): GenericParameterInduction {
    const variant = jsonString(value);

    switch (variant) {
        case "parameterConstraint":
            return "parameterConstraint";
        case "storageConstraint":
            return "storageConstraint";
        case "form":
            return "form";
        case "comptime":
            return "comptime";
    }

    throw new SerdeError(`unknown enum variant: ${variant}`);
}
